import calendar
from datetime import date, timedelta


def due_date(issued: date, terms: str) -> date:
    if terms == "NET30":
        return issued + timedelta(days=30)
    if terms == "NET60":
        return issued + timedelta(days=60)
    if terms == "EOM":
        last = calendar.monthrange(issued.year, issued.month)[1]
        return issued.replace(day=last)
    raise ValueError(f"unknown terms: {terms}")

