export const isEmail = (s) => typeof s === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s)

export function isStrongPassword(p) {
  if (typeof p !== 'string' || p.length < 12) return false
  return /[A-Z]/.test(p) && /[a-z]/.test(p) && /\d/.test(p)
}
